/**
 * A request that joins an in-flight planning of the same key waits for the owner's result until the owner's hard stop:
 * the owner's deadline plus the deadline's own length, measured from the owner's budget creation. Every budget in these
 * tests reads one shared test clock that only the test advances, so each instant is placed exactly; the owner is held
 * inside its search by a latch.
 */
class PackedPlanCacheFlightWaiterTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final String WAITER_FALLBACK = "optimizer.planCacheFlightWaiterFallback";
	/** The goal's absolute deadline. It lies in the real past; only the test clock decides what has expired. */
	private static final long DEADLINE = System.nanoTime() - TimeUnit.HOURS.toNanos(1L);
	/** The owner's deadline length: its budget is created this long before the deadline. */
	private static final long LENGTH = 1_000_000L;
	private static final long OWNER_HARD_STOP = DEADLINE + LENGTH;

	private final AtomicLong now = new AtomicLong();
	private final AtomicInteger plannings = new AtomicInteger();
	private final CountDownLatch ownerSearching = new CountDownLatch(1);
	private final CountDownLatch releaseOwner = new CountDownLatch(1);
	private final AtomicBoolean failOwner = new AtomicBoolean();
	private final AtomicReference<Thread> ownerThread = new AtomicReference<>();
	private final PackedPlanCache cache = new PackedPlanCache(8, 1);
	private final PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L);
	private final ExecutorService owner = Executors.newSingleThreadExecutor();

	@AfterEach
	void releaseTheOwner() {
		releaseOwner.countDown();
		owner.shutdownNow();
	}

	@Test
	void ownerFinishingWithinItsGraceAfterTheDeadlineIsAwaitedByTheWaiter() throws Exception {
		OptimizationGoal goal = budgeted();
		Future<PackedPlanningResult> owned = startOwner(goal);
		Waiter waiter = startWaiter(goal, DEADLINE - LENGTH / 2L);
		waiter.awaitWaiting();

		now.set(DEADLINE + LENGTH / 2L);
		waiter.awaitPolling(2);
		assertFalse(waiter.finished(), "past the owner's deadline but within its grace the waiter keeps waiting");

		releaseOwner.countDown();
		PackedPlanningResult ownerResult = owned.get(30L, TimeUnit.SECONDS);
		PackedPlanningResult waited = waiter.result();

		assertTrue(ownerResult.totalPrice().isPresent(), "fixture: the owner finds a priced plan in its grace");
		assertTrue(waited.metrics().planCacheHit(), "the waiter receives the owner's published plan");
		assertEquals(ownerResult.totalPrice(), waited.totalPrice());
		assertEquals(1, plannings.get(), "the planner ran once, for the owner");
		assertNull(waited.selectedPlan().getStringMetricPlanned(WAITER_FALLBACK));
	}

	@Test
	void ownerThatNeverPublishesIsAbandonedAtItsHardStopNotBefore() throws Exception {
		OptimizationGoal goal = budgeted();
		startOwner(goal);
		Waiter waiter = startWaiter(goal, DEADLINE - LENGTH / 2L);
		waiter.awaitWaiting();

		now.set(OWNER_HARD_STOP - 1L);
		waiter.awaitPolling(2);
		assertFalse(waiter.finished(), "the waiter keeps waiting until the owner's hard stop");

		now.set(OWNER_HARD_STOP);
		PackedPlanningResult waited = waiter.result();

		assertEquals("owner-hard-stop", waited.selectedPlan().getStringMetricPlanned(WAITER_FALLBACK),
				"the waiter's own planning after the owner's hard stop is marked");
		assertFalse(waited.metrics().planCacheHit());
		assertFalse(waited.totalPrice().isPresent(), "no time is left: the mandatory fallback, as today");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, waited.completionStatus());
		assertTrue(waited.selectedPlan().getDoubleMetricPlanned("optimizer.mandatoryFallbackWorkUnits") > 0.0d);
		assertEquals(1, plannings.get(), "only the owner opened a provider session");
	}

	@Test
	void interruptedWaiterStopsWaitingAtOnce() throws Exception {
		OptimizationGoal goal = budgeted();
		startOwner(goal);
		Waiter waiter = startWaiter(goal, DEADLINE - LENGTH / 2L);
		waiter.awaitWaiting();

		waiter.thread.interrupt();
		Throwable failure = waiter.failure();

		assertInstanceOf(IllegalStateException.class, failure, () -> "the interrupt ends the wait: " + failure);
		assertInstanceOf(InterruptedException.class, failure.getCause());
		assertEquals(DEADLINE - LENGTH / 2L, now.get(), "without any time passing");
		assertEquals(1, plannings.get());
	}

	@Test
	void ownerFailureWakesTheWaiterAtOnceAndItPlansForItself() throws Exception {
		OptimizationGoal goal = budgeted();
		Future<PackedPlanningResult> owned = startOwner(goal);
		Waiter waiter = startWaiter(goal, DEADLINE - LENGTH / 2L);
		waiter.awaitWaiting();
		assertFalse(waiter.finished(), "fixture: the waiter is waiting when the owner fails");

		failOwner.set(true);
		releaseOwner.countDown();
		PackedPlanningResult waited = waiter.result();

		ExecutionException ownerFailure = org.junit.jupiter.api.Assertions.assertThrows(ExecutionException.class,
				() -> owned.get(30L, TimeUnit.SECONDS));
		assertEquals("owner failed", ownerFailure.getCause().getMessage());
		assertFalse(waited.metrics().planCacheHit());
		assertTrue(waited.totalPrice().isPresent(), "before the deadline the waiter's own search finds a price");
		assertEquals(2, plannings.get(), "the waiter planned for itself");
		assertEquals(DEADLINE - LENGTH / 2L, now.get(), "it woke without any time passing");
		assertNull(waited.selectedPlan().getStringMetricPlanned(WAITER_FALLBACK));
	}

	@Test
	void twoWaitersBothReceiveTheOwnersPlan() throws Exception {
		OptimizationGoal goal = budgeted();
		Future<PackedPlanningResult> owned = startOwner(goal);
		Waiter first = startWaiter(goal, DEADLINE - LENGTH / 2L);
		first.awaitWaiting();
		Waiter second = startWaiter(goal, DEADLINE - LENGTH / 2L);
		second.awaitWaiting();
		assertFalse(first.finished());

		releaseOwner.countDown();
		PackedPlanningResult ownerResult = owned.get(30L, TimeUnit.SECONDS);

		assertTrue(first.result().metrics().planCacheHit());
		assertTrue(second.result().metrics().planCacheHit());
		assertEquals(ownerResult.totalPrice(), first.result().totalPrice());
		assertEquals(ownerResult.totalPrice(), second.result().totalPrice());
		assertEquals(1, plannings.get());
	}

	/** Without a deadline the waiter waits for the owner without bound, but its own interrupt still ends the wait. */
	@Test
	void waiterWithoutADeadlineWaitsForTheOwnerAndStillStopsWhenInterrupted() throws Exception {
		OptimizationGoal root = OptimizationGoal.root();
		OptimizationGoal goal = new OptimizationGoal(root.requiredProperties(), root.semanticScope(),
				root.costPolicy(), root.costBound(), root.excludedProperties(), OptimizationGoal.SearchMode.AUTO,
				Long.MAX_VALUE, 10_000, root.rowGoal(), root.estimationTier(), root.inputBindingContext());
		Future<PackedPlanningResult> owned = startOwner(goal);
		Waiter interrupted = startWaiter(goal, DEADLINE);
		Waiter patient = startWaiter(goal, DEADLINE);
		interrupted.awaitBlocked();
		patient.awaitBlocked();

		interrupted.thread.interrupt();
		Throwable failure = interrupted.failure();
		assertInstanceOf(IllegalStateException.class, failure, () -> "the interrupt ends the wait: " + failure);
		assertFalse(patient.finished(), "the other waiter keeps waiting for the owner");

		releaseOwner.countDown();
		PackedPlanningResult ownerResult = owned.get(30L, TimeUnit.SECONDS);
		assertTrue(patient.result().metrics().planCacheHit());
		assertEquals(ownerResult.totalPrice(), patient.result().totalPrice());
		assertEquals(1, plannings.get());
	}

	/** Exact mode has no overrun, so its hard stop is its deadline: a waiter stops waiting there, as before. */
	@Test
	void exactModeWaiterStopsAtTheOwnersDeadline() throws Exception {
		OptimizationGoal root = OptimizationGoal.root();
		OptimizationGoal goal = new OptimizationGoal(root.requiredProperties(), root.semanticScope(),
				root.costPolicy(), root.costBound(), root.excludedProperties(), OptimizationGoal.SearchMode.EXACT,
				DEADLINE, 10_000, root.rowGoal(), root.estimationTier(), root.inputBindingContext());
		startOwner(goal);
		Waiter waiter = startWaiter(goal, DEADLINE - LENGTH / 2L);
		waiter.awaitWaiting();
		assertFalse(waiter.finished(), "the waiter waits until the owner's deadline");

		now.set(DEADLINE);
		PackedPlanningResult waited = waiter.result();

		assertFalse(waited.metrics().planCacheHit());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, waited.completionStatus());
		assertEquals(1, plannings.get());
	}

	private OptimizationGoal budgeted() {
		OptimizationGoal root = OptimizationGoal.root();
		return new OptimizationGoal(root.requiredProperties(), root.semanticScope(), root.costPolicy(),
				root.costBound(), root.excludedProperties(), OptimizationGoal.SearchMode.BUDGETED, DEADLINE, 10_000,
				root.rowGoal(), root.estimationTier(), root.inputBindingContext());
	}

	/** The owner's budget is created at {@code DEADLINE - LENGTH}; the owner is then held in its first estimate. */
	private Future<PackedPlanningResult> startOwner(OptimizationGoal goal) {
		now.set(DEADLINE - LENGTH);
		Future<PackedPlanningResult> owned = owner.submit(() -> {
			ownerThread.set(Thread.currentThread());
			PackedSearchBudget.CLOCK_FOR_TESTS.set(sharedClock(null));
			try {
				return PackedCascadesPlanner.optimize(projectedChain(), goal, cache, context, model());
			} finally {
				PackedSearchBudget.CLOCK_FOR_TESTS.remove();
			}
		});
		await(ownerSearching);
		return owned;
	}

	private Waiter startWaiter(OptimizationGoal goal, long arrival) {
		now.set(arrival);
		Waiter waiter = new Waiter();
		waiter.thread = new Thread(() -> {
			PackedSearchBudget.CLOCK_FOR_TESTS.set(sharedClock(waiter.clockReads));
			try {
				waiter.result.set(PackedCascadesPlanner.optimize(projectedChain(), goal, cache, context, model()));
			} catch (Throwable failure) {
				waiter.failure.set(failure);
			} finally {
				PackedSearchBudget.CLOCK_FOR_TESTS.remove();
				waiter.done.countDown();
			}
		});
		waiter.thread.start();
		return waiter;
	}

	private ToLongFunction<PackedSearchBudget> sharedClock(AtomicInteger reads) {
		return budget -> {
			if (reads != null) {
				reads.incrementAndGet();
			}
			return now.get();
		};
	}

	private final class Waiter {
		private Thread thread;
		private final AtomicInteger clockReads = new AtomicInteger();
		private final AtomicReference<PackedPlanningResult> result = new AtomicReference<>();
		private final AtomicReference<Throwable> failure = new AtomicReference<>();
		private final CountDownLatch done = new CountDownLatch(1);

		/**
		 * Returns once the waiter polls its wait for the owner (its budget reads the clock twice before it joins the
		 * flight, at its creation and at its first deadline sample; every further reading is a poll of the wait), or
		 * once it has finished.
		 */
		void awaitWaiting() {
			spinUntil(() -> clockReads.get() >= 4 || finished(), "the waiter to wait for the owner");
		}

		/** Returns once the waiter has read the clock {@code reads} more times, or has finished. */
		void awaitPolling(int reads) {
			int target = clockReads.get() + reads;
			spinUntil(() -> clockReads.get() >= target || finished(), "the waiter to read the clock");
		}

		/** Returns once the waiter thread is parked without a timeout (an unbounded wait), or has finished. */
		void awaitBlocked() {
			spinUntil(() -> thread.getState() == Thread.State.WAITING || finished(), "the waiter to block");
		}

		boolean finished() {
			return done.getCount() == 0L;
		}

		PackedPlanningResult result() throws InterruptedException {
			if (!done.await(30L, TimeUnit.SECONDS)) {
				fail("the waiter did not finish");
			}
			if (failure.get() != null) {
				throw new AssertionError("the waiter failed", failure.get());
			}
			return result.get();
		}

		Throwable failure() throws InterruptedException {
			if (!done.await(30L, TimeUnit.SECONDS)) {
				fail("the waiter did not finish");
			}
			return failure.get();
		}
	}

	private static void spinUntil(BooleanSupplier condition, String what) {
		long bound = System.nanoTime() + TimeUnit.SECONDS.toNanos(30L);
		while (!condition.getAsBoolean()) {
			if (System.nanoTime() > bound) {
				fail("timed out waiting for " + what);
			}
			Thread.onSpinWait();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(30L, TimeUnit.SECONDS)) {
				throw new AssertionError("test latch was not released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted", interrupted);
		}
	}

	/** SELECT ?v0 ?v4 over ?v0 p1 ?v1 . ?v1 p2 ?v2 . ?v2 p3 ?v3 . ?v3 p4 ?v4, written as a left-deep chain. */
	private static TupleExpr projectedChain() {
		TupleExpr chain = new Join(new Join(new Join(pattern("v0", "urn:p1", "v1"), pattern("v1", "urn:p2", "v2")),
				pattern("v2", "urn:p3", "v3")), pattern("v3", "urn:p4", "v4"));
		return new Projection(chain, new ProjectionElemList(new ProjectionElem("v0"), new ProjectionElem("v4")));
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate.substring(4) + "Predicate",
				VALUES.createIRI(predicate), true, true), Var.of(object));
	}

	private static double rows(PackedQueryView query, int relationId) {
		return switch (query.statementPatternValue(relationId, 1).stringValue()) {
		case "urn:p1" -> 40.0d;
		case "urn:p2" -> 300.0d;
		case "urn:p3" -> 7.0d;
		default -> 900.0d;
		};
	}

	/**
	 * Prices every pattern standalone and per invocation under any prefix. It counts provider sessions (one per
	 * planning) and holds the owner in its first estimate until the test releases it, optionally failing it then.
	 */
	private PackedCostModel model() {
		AtomicBoolean held = new AtomicBoolean();
		return new PackedCostModel() {
			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				plannings.incrementAndGet();
				return PackedCostSession.scalar(this, query);
			}

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? rows(query, relationId) : Double.NaN;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (Thread.currentThread() == ownerThread.get() && held.compareAndSet(false, true)) {
					ownerSearching.countDown();
					await(releaseOwner);
					if (failOwner.get()) {
						throw new IllegalStateException("owner failed");
					}
				}
				if (!query.isStatementPattern(relationId)) {
					return;
				}
				double rows = rows(query, relationId);
				if (context.prefixRelationCount() == 0) {
					output.setRows(rows, rows);
					output.setLocalPhysicalCost(rows, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, rows, 0.0d, 0.0d);
					return;
				}
				double invocations = Math.max(1.0d, context.prefixRows());
				double contextual = invocations * Math.max(1.0d, rows / 50.0d);
				output.setContextualRows(contextual, contextual);
				output.setLocalPhysicalCost(contextual, invocations, invocations, 0.0d, 0.0d, 0.0d, 0.0d,
						contextual, 0.0d, 0.0d);
				output.setInvocations(invocations);
			}
		};
	}
}
